WITH latest_flows AS (
    SELECT trade_date, fii_net_today, dii_net_today, fii_net_5d, dii_net_5d, flow_signal, fii_trend, dii_trend
    FROM signals.fii_dii_flows
    WHERE trade_date >= (CURRENT_DATE - INTERVAL '3 months')
)
SELECT * FROM latest_flows;

WITH regime_data AS (
    SELECT trade_date, regime, confidence, days_in_regime
    FROM signals.regime_history
    WHERE trade_date >= (CURRENT_DATE - INTERVAL '3 months')
)
SELECT * FROM regime_data;

WITH market_breadth AS (
    SELECT trade_date, advances, declines, adv_volume, dec_volume, net_ad, ad_signal
    FROM breadth.market_daily
    WHERE trade_date >= (CURRENT_DATE - INTERVAL '3 months')
)
SELECT * FROM market_breadth;

WITH index_data AS (
    SELECT trade_date, index_symbol, close, change_pct, rsi, trend_signal
    FROM market.index_eod
    WHERE trade_date >= (CURRENT_DATE - INTERVAL '3 months')
)
SELECT * FROM index_data WHERE index_symbol = 'Nifty 50';
